{
  "response_type": "answer",
  "answer": "For a 17-business-day work-location change within Canada, the employee must first receive manager approval, but since the change exceeds 15 business days, it requires additional review by People Operations before approval. For a cross-border remote-work exception, the request must be reviewed by People Operations and Legal before approval due to tax, employment, and security implications.",
  "citations": [
    {
      "document_id": "HR-003",
      "document_title": "Remote and Hybrid Work Policy",
      "section_heading": "Approval Requirements",
      "chunk_id": "47b76ced-caf6-4234-b966-1a9cbde9e540",
      "citation_text": "A temporary change within the same country for fewer than 15 business days may be approved by the manager. Longer changes require People Operations review."
    },
    {
      "document_id": "HR-003",
      "document_title": "Remote and Hybrid Work Policy",
      "section_heading": "Cross-Border Work",
      "chunk_id": "4d9b5b5a-6038-4f40-9321-f262d3aa7fd9",
      "citation_text": "Temporary cross-border work requires People Operations review before travel. Requests to work outside Canada or the United States are considered ambiguous until People Operations reviews tax, employment, and security implications."
    },
    {
      "document_id": "HR-ADMIN-001",
      "document_title": "HR Policy Operations Guide",
      "section_heading": "Escalation Paths",
      "chunk_id": "9c765ed4-54be-43ed-a663-8cc12d7ff3b7",
      "citation_text": "Remote work exceptions involving cross-border work should be reviewed with People Operations and Legal before approval."
    }
  ],
  "supported_claims": [
    "17-business-day work-location change within Canada requires manager approval and People Operations review",
    "Cross-border remote-work exceptions require People Operations and Legal review before approval"
  ],
  "unsupported_claims": [],
  "validation_notes": "The answer is fully supported by the retrieved policy excerpts specifying approval requirements for work-location changes and cross-border remote work."
}
